public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLen = 0;
    for (String s : strings) {
        if (s == null) continue;
        maxLen = Math.max(maxLen, s.length());
    }

    // Check all possible lengths from maxLen down to 1
    for (int len = maxLen; len >= 1; len--) {
        // Collect all substrings of length len from all strings, and their reverses
        Set<String> candidates = new HashSet<>();
        for (String s : strings) {
            if (s == null || s.length() < len) continue;
            for (int i = 0; i <= s.length() - len; i++) {
                String sub = s.substring(i, i + len);
                candidates.add(sub);
                // Add reverse as well
                candidates.add(new StringBuilder(sub).reverse().toString());
            }
        }

        // For each candidate, check if it or its reverse appears as a substring in any of the strings
        for (String candidate : candidates) {
            String reverse = new StringBuilder(candidate).reverse().toString();
            boolean found = false;
            for (String s : strings) {
                if (s == null) continue;
                if (s.contains(candidate) || s.contains(reverse)) {
                    found = true;
                    break;
                }
            }
            if (found) {
                return len;
            }
        }
    }

    return 0;
}
