public static String appx(String word1, String word2) {
    int common = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                common++;
                break;
            }
        }
    }
    int sum = word1.length() + word2.length();
    int gcd = gcd(common, sum);
    int numerator = common / gcd;
    int denominator = sum / gcd;
    String result;
    if (denominator == 1) {
        result = String.valueOf(numerator);
    } else {
        result = numerator + "/" + denominator;
    }
    return "appx(" + word1 + ", " + word2 + ") = " + result;
}

private static int gcd(int a, int b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}
