public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;

    int sum = 0;
    for (int num : nums) sum += num;

    // We need to find a subset of size k (1 <= k <= n-1) such that
    // sum(subset) / k == sum / n
    // => sum(subset) * n == sum * k
    // => sum(subset) == sum * k / n
    // So sum * k must be divisible by n.

    // To optimize, we can use the fact that if a subset of size k works,
    // then a subset of size n-k also works (the complement).
    // So we only need to check k from 1 to n/2.

    // Also, we can use a DP approach: dp[k][s] = true if we can form a subset of size k with sum s.
    // But s can be large. Let's think of a better way.

    // Alternative: use a set of possible sums for each size.
    // For each k from 1 to n/2, check if sum * k % n == 0, and if so, check if sum * k / n is achievable.

    // Let's use a boolean DP: dp[k][s] where s is the sum.
    // The maximum sum is sum, which can be up to 10000 * 1000 = 10^7, which is too large for a 2D array.

    // Instead, we can use a set of integers for each k.
    // For k from 1 to n/2, maintain a set of possible sums.

    int maxK = n / 2;
    // dp[k] is a set of possible sums for subsets of size k
    Set<Integer>[] dp = new Set[maxK + 1];
    for (int i = 0; i <= maxK; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0);

    for (int num : nums) {
        // Iterate backwards to avoid using the same element multiple times
        for (int k = maxK; k >= 1; k--) {
            for (int s : dp[k - 1]) {
                dp[k].add(s + num);
            }
        }
    }

    for (int k = 1; k <= maxK; k++) {
        if (sum * k % n == 0) {
            int target = sum * k / n;
            if (dp[k].contains(target)) {
                return true;
            }
        }
    }

    return false;
}
