public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n == 0) {
        return result;
    }
    // Pairs: (left, right)
    // For the outermost pair, left cannot be 0 (unless n == 1)
    // For inner pairs, left can be 0
    char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};

    // Build from the outside in
    // We'll use a recursive approach or iterative building
    // Let's use a helper method

    buildCenterSymmetric(n, 0, new StringBuilder(), pairs, result, true);
    return result;
}

private static void buildCenterSymmetric(int n, int depth, StringBuilder sb, char[][] pairs, List<String> result, boolean isOutermost) {
    if (depth == n / 2) {
        // If n is odd, we need to add the middle character
        if (n % 2 == 1) {
            // Middle can be 0, 1, 8
            for (char c : new char[]{'0', '1', '8'}) {
                StringBuilder temp = new StringBuilder(sb);
                temp.append(c);
                // Now append the reverse of the right side
                for (int i = sb.length() - 1; i >= 0; i--) {
                    temp.append(sb.charAt(i));
                }
                result.add(temp.toString());
            }
        } else {
            StringBuilder temp = new StringBuilder(sb);
            for (int i = sb.length() - 1; i >= 0; i--) {
                temp.append(sb.charAt(i));
            }
            result.add(temp.toString());
        }
        return;
    }

    for (char[] pair : pairs) {
        char left = pair[0];
        char right = pair[1];
        // If this is the outermost pair and n > 1, left cannot be 0
        if (depth == 0 && n > 1 && left == '0') {
            continue;
        }
        sb.append(left);
        sb.append(right);
        buildCenterSymmetric(n, depth + 1, sb, pairs, result, false);
        sb.deleteCharAt(sb.length() - 1);
        sb.deleteCharAt(sb.length() - 1);
    }
}
